  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਕਲ ਦੇ ਇਤਿਹਾਸਕ ਵਿਕਾਸ ਬਾਰੇ ਲਿਖੋ, ਖਾਸ ਕਰਕੇ ਪਹਿਲਾਂ ਪ੍ਰਚਲਿਤ ਸਾਈਕਲਾਂ ਤੋਂ ਲੈ ਕੇ ਔਰਤਾਂ ਅਤੇ ਬੱਚਿਆਂ ਲਈ ਬਣੇ ਸਾਈਕਲਾਂ ਤੱਕ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜਕੱਲ੍ਹ ਉਪਲਬਧ ਸਾਈਕਲ ਦੇ ਵੱਖ-ਵੱਖ ਪ੍ਰਕਾਰਾਂ ਦਾ ਵਰਣਨ ਕਰੋ ਅਤੇ ਉਹਨਾਂ ਦੀ ਵਰਤੋਂ ਬਾਰੇ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
