  ('e943079b-77f5-46df-87d6-f89c01cf1379', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੁਧਿਆਣਾ ਦੇ ਸਾਈਕਲ ਉਦਯੋਗ ਨੇ ਸਿਰਫ਼ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ, ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਆਪਣੀ ਮਾਨਤਾ ਬਣਾਈ ਹੈ। ਇੱਥੇ ਤਿਆਰ ਕੀਤੀਆਂ ਸਾਈਕਲਾਂ ਮਜ਼ਬੂਤ ਫਰੇਮ, ਪਾਏਦਾਰ ਚੱਕਰ ਅਤੇ ਆਰਾਮਦਾਇਕ ਸਵਾਰੀ ਲਈ ਜਾਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
