  ('465fb818-bfa1-4aa2-a2a9-73479771ddc5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਵਾਜਾਈ - ਆਉਣਾ-ਜਾਣਾ (transport), ਆਮਦ - ਖੋਜ (invention), ਸਨਅਤ - ਉਦਯੋਗ (industry)Í$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
  ('34d81bd0-0db4-47a2-80b8-837119cfb426', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਕਲ ਦਾ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਸਾਈਕਲ ਦਾ ਮਹੱਤਵ ਅਤੇ ਸਾਈਕਲ ਉਦਯੋਗ ਬਾਰੇ ਸਮਝ ਦਾ ਵਿਕਾਸ ਕਰਨਾ ਹੈ। ਸਾਈਕਲ ਸਾਡੇ ਜੀਵਨ ਦਾ ਅਹਿਮ ਹਿੱਸਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 1, NULL),
  ('b085acdf-7d8c-4aa3-b662-f004ff146340', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਕਲ ਦੀ ਖੋਜ ਨੇ ਮਨੁੱਖੀ ਜੀਵਨ ਨੂੰ ਕਈ ਪੱਖਾਂ ਤੋਂ ਸੁਖਾਲਾ ਕੀਤਾ ਹੈ। ਪਹਿਲਾਂ, ਇਸ ਨਾਲ ਲੋਕ ਲੰਮੀਆਂ ਦੂਰੀਆਂ ਤੇਜ਼ੀ ਨਾਲ ਸਰ ਕਰਨ ਦੇ ਯੋਗ ਹੋਏ। ਦੂਜਾ, ਸਾਈਕਲ ਨਾਲ ਸਰੀਰ ਦੀ ਕਸਰਤ ਹੁੰਦੀ ਹੈ ਜੋ ਮਨੁੱਖ ਨੂੰ ਤੰਦਰੁਸਤੀ ਦੇ ਰਾਹ 'ਤੇ ਲਿਜਾਂਦੀ ਹੈ। ਸਵੇਰੇ ਅਤੇ ਸ਼ਾਮ ਨੂੰ ਸਾਈਕਲ ਚਲਾਉਣਾ ਦਿਲ ਅਤੇ ਮਾਸਪੇਸ਼ੀਆਂ ਲਈ ਬੜਾ ਉਪਯੋਗੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cb36ad10-d6db-4560-b3f9-e8ab61097a91', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ, ਸਾਈਕਲ ਆਰਥਿਕ ਪੱਖੋਂ ਵੀ ਲਾਹੇਵੰਦ ਹੈ। ਇਸ ਦੀ ਕੀਮਤ ਹੋਰਨਾਂ ਸਾਧਨਾਂ ਦੇ ਮੁਕਾਬਲੇ ਬੜੀ ਘੱਟ ਹੁੰਦੀ ਹੈ। ਚੌਥਾ, ਇਹ ਵਾਤਾਵਰਨ ਪੱਖੀ ਸਵਾਰੀ ਹੈ। ਇਹ ਚਲਾਉਂਦਿਆਂ ਨਾ ਤਾਂ ਕੋਈ ਧੂੰਆਂ ਹੁੰਦਾ ਹੈ ਅਤੇ ਨਾ ਹੀ ਕੋਈ ਸ਼ੋਰ ਪ੍ਰਦੂਸ਼ਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('989ae3cc-8edc-4b46-9dde-66034f2a5d76', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੋਈ ਜ਼ਮਾਨਾ ਸੀ ਜਦੋਂ ਕੇਵਲ ਇੱਕੋ ਤਰ੍ਹਾਂ ਦੇ ਸਾਈਕਲ ਪ੍ਰਚਲਿਤ ਸਨ। ਇਹ ਆਮ ਤੌਰ 'ਤੇ ਵੱਡਿਆਂ ਲਈ ਹੀ ਬਣਾਏ ਜਾਂਦੇ ਸਨ। ਛੋਟੇ ਬੱਚੇ ਇਹਨਾਂ ਨੂੰ ਪਹਿਲਾਂ ਕੈਂਚੀ ਚਲਾਉਣਾ ਸਿੱਖਦੇ ਸਨ। ਫਿਰ ਔਰਤਾਂ ਲਈ 'ਲੇਡੀ ਸਾਈਕਲ' ਬਣੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('798b9fac-f768-49ae-a50e-aee05ec12b11', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੌਲੀ-ਹੌਲੀ ਬੱਚਿਆਂ ਲਈ ਅਲੱਗ ਸਾਈਕਲ, ਦੌੜ ਲਈ ਅਲੱਗ ਅਤੇ ਪਹਾੜਾਂ ਦੀਆਂ ਚੜ੍ਹਾਈਆਂ ਲਈ ਅਲੱਗ ਸਾਈਕਲ ਬਣਨ ਲੱਗੇ। ਅੱਜ ਸਾਈਕਲ ਦੇ ਕਈ ਪ੍ਰਕਾਰ ਉਪਲਬਧ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6d543a7f-bd9a-4d62-8bb9-be96f67466ab', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਊਂਟੇਨ ਬਾਈਕ ਖੁੱਲ੍ਹੇ ਰਾਹਾਂ ਲਈ ਹੈ, ਰੋਡ ਬਾਈਕ ਤੇਜ਼ ਅਤੇ ਲੰਬੀ ਦੂਰੀ ਲਈ, ਹਾਈਬ੍ਰਿਡ ਬਾਈਕ ਦਿਨ-ਬ-ਦਿਨ ਦੀ ਸਵਾਰੀ ਲਈ ਅਤੇ ਈ-ਬਾਈਕ ਮੋਟਰ ਦੀ ਸਹਾਇਤਾ ਨਾਲ ਘੱਟ ਮਿਹਨਤ ਵਾਲੀ ਸਵਾਰੀ ਲਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8e3b7e72-7ad2-4d01-b781-c253ded57bba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫੋਲਡਿੰਗ ਬਾਈਕ ਨਵੀਂ ਤਕਨੀਕ ਦਾ ਕਮਾਲ ਹੈ। ਇਸ ਨੂੰ ਇਕੱਠਾ ਕਰ ਕੇ ਬੈਗ ਵਿੱਚ ਪਾ ਕੇ ਦੂਜੀ ਥਾਂ ਲਿਜਾਇਆ ਜਾ ਸਕਦਾ ਹੈ। ਬੱਚਿਆਂ ਲਈ 'ਬੈਲੰਸ ਬਾਈਕ' ਪੈਡਲ ਤੋਂ ਬਿਨਾਂ ਬਣਾਈ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਜੋ ਉਹ ਬਾਈਕ ਚਲਾਉਣਾ ਸਿੱਖ ਸਕਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('944b0fe1-9d81-490e-ba35-a4ddd86d6b50', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭਾਰਤ ਵਿੱਚ ਲੁਧਿਆਣਾ ਸਾਈਕਲ ਉਦਯੋਗ ਲਈ ਪ੍ਰਸਿੱਧ ਹੈ। ਲੁਧਿਆਣਾ ਨੂੰ 'ਸਾਈਕਲ ਸਿਟੀ' ਵੀ ਕਿਹਾ ਜਾਂਦਾ ਹੈ। ਲੁਧਿਆਣਾ ਦੀ ਸਾਈਕਲ ਸਨਅਤ ਸਨ 1980 ਦੇ ਦੌਰਾਨ ਤੇਜ਼ੀ ਨਾਲ ਵਿਕਸਤ ਹੋਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('79318aae-6b51-433a-921e-8978a33fe795', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ੁਰੂ ਵਿੱਚ ਛੋਟੇ-ਛੋਟੇ ਉਦਯੋਗਾਂ ਨੇ ਸਾਈਕਲ ਦੇ ਚੱਕਰ ਅਤੇ ਫਰੇਮ ਤਿਆਰ ਕਰਨੇ ਸ਼ੁਰੂ ਕੀਤੇ। ਸਹਿਜੇ-ਸਹਿਜੇ ਇਹ ਉਦਯੋਗ ਵੱਡੇ ਕਾਰਖਾਨਿਆਂ ਵਿੱਚ ਤਬਦੀਲ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f8bbbc64-fdc4-4359-b4b8-d8394818914e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੁਧਿਆਣਾ ਦੇ ਸਾਈਕਲ ਉਦਯੋਗ ਨੇ ਸਿਰਫ਼ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ, ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਆਪਣੀ ਮਾਨਤਾ ਬਣਾਈ ਹੈ। ਇੱਥੇ ਤਿਆਰ ਕੀਤੀਆਂ ਸਾਈਕਲਾਂ ਮਜ਼ਬੂਤ ਫਰੇਮ, ਪਾਏਦਾਰ ਚੱਕਰ ਅਤੇ ਆਰਾਮਦਾਇਕ ਸਵਾਰੀ ਲਈ ਜਾਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਇੱਥੇ ਹਾਈਬ੍ਰਿਡ ਬਾਈਕ, ਮਾਊਂਟੇਨ ਬਾਈਕ, ਰੋਡ ਬਾਈਕ ਅਤੇ ਬੱਚਿਆਂ ਲਈ ਸਾਈਕਲ ਤਿਆਰ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਉਦਯੋਗ ਵਿੱਚ ਨਵੇਂ ਮਾਡਲਾਂ ਅਤੇ ਨਵੀਨਤਮ ਡਿਜ਼ਾਈਨਾਂ ਦੀ ਖੋਜ ਵੀ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਲੁਧਿਆਣਾ ਦੀ ਸਾਈਕਲ ਸਨਅਤ ਨੇ ਸਥਾਨਕ ਲੋਕਾਂ ਨੂੰ ਰੁਜ਼ਗਾਰ ਦੇ ਕੇ ਸ਼ਹਿਰ ਦੀ ਆਰਥਿਕਤਾ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਇਆ ਹੈ। ਇਸ ਨਾਲ ਸਿਰਫ਼ ਸ਼ਹਿਰ ਹੀ ਨਹੀਂ, ਸਗੋਂ ਸਾਰੇ ਪੰਜਾਬ ਅਤੇ ਭਾਰਤ ਵਿੱਚ ਸਾਈਕਲ ਸਵਾਰੀ ਆਸਾਨ ਹੋਈ ਹੈ। ਇੱਥੋਂ ਦੀ ਸਾਈਕਲ ਕੰਪਨੀ 'ਹੀਰੋ' ਦੇ ਬਣੇ ਸਾਈਕਲਾਂ ਨੂੰ ਕੌਣ ਨਹੀਂ ਜਾਣਦਾ! ਕੁਝ ਸਾਲ ਪਹਿਲਾਂ ਤੱਕ ਤਕਰੀਬਨ ਹਰੇਕ ਘਰ ਵਿੱਚ ਹੀਰੋ ਦਾ ਸਾਈਕਲ ਆਮ ਹੁੰਦਾ ਸੀ। ਸਾਈਕਲ ਦੀ ਖੋਜ ਅਤੇ ਲੁਧਿਆਣਾ ਦੀ ਸਨਅਤ ਸਾਨੂੰ ਇਹ ਸਿਖਾਉਂਦੀ ਹੈ ਕਿ ਮਨੁੱਖੀ ਕੌਸ਼ਲ, ਖੋਜ ਅਤੇ ਉਦਯੋਗਿਕ ਯੋਗਦਾਨ ਸਮਾਜ ਦੇ ਵਿਕਾਸ ਲਈ ਬਹੁਤ ਮਹੱਤਵਪੂਰਨ ਹਨ। ਇਹ ਨਾ ਸਿਰਫ਼ ਆਵਾਜਾਈ ਦਾ ਸਾਧਨ ਹੈ, ਬਲਕਿ ਮਨੁੱਖੀ ਜੀਵਨ ਵਿੱਚ ਸੁਖਮਈ, ਸਿਹਤਮੰਦ ਅਤੇ ਆਰਥਿਕ ਤਰੱਕੀ ਲਿਆਉਣ ਵਾਲੀ ਖੋਜ ਹੈ। ਸੰਸਾਰ ਭਰ ਵਿੱਚ 'ਵਿਸ਼ਵ ਸਾਈਕਲ ਦਿਵਸ' ਹਰ ਸਾਲ 3 ਜੂਨ ਨੂੰ ਮਨਾਇਆ ਜਾਂਦਾ ਹੈ। ਅੱਜ-ਕੱਲ੍ਹ ਵਿਕਸਿਤ ਮੁਲਕਾਂ ਵਿੱਚ ਵੀ ਸਾਈਕਲ ਚਲਾਉਣ ਦਾ ਰੁਝਾਨ ਜ਼ੋਰਾਂ ਉੱਤੇ ਹੈ। ਜਪਾਨ ਅਤੇ ਯੂਰਪ ਦੇ ਕਈ ਮੁਲਕਾਂ ਵਿੱਚ ਲੋਕ ਕਾਰਾਂ ਦੀ ਥਾਂ ਮੁੜ ਸਾਈਕਲ ਦੀ ਵਰਤੋਂ ਵਧਾ ਰਹੇ ਹਨ। ਜਿਉਂ-ਜਿਉਂ ਮਨੁੱਖ ਵਾਤਾਵਰਨ ਸੰਬੰਧੀ ਗੰਭੀਰ ਚੁਣੌਤੀਆਂ ਦੇ ਰੂ-ਬ-ਰੂ ਹੋ ਰਿਹਾ ਹੈ, ਤਿਉਂ-ਤਿਉਂ ਸਾਈਕਲ ਦੀ ਮਹੱਤਤਾ ਨੂੰ ਸਵੀਕਾਰ ਰਿਹਾ ਹੈ। * ਸਾਈਕਲ ਦੀ ਵਰਤੋਂ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ। * ਲੁਧਿਆਣਾ ਦੀ ਸਾਈਕਲ ਸਨਅਤ ਬਾਰੇ ਜਾਣਕਾਰੀ ਵਿੱਚ ਵਾਧਾ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਪਾਏਦਾਰ - ਮਜ਼ਬੂਤ, ਨਵੀਨਤਮ - ਸਭ ਤੋਂ ਤਾਜ਼ਾ, ਯੋਗਦਾਨ- ਸਹਾਇਤਾ, ਚੁਣੌਤੀ - ਔਖਿਆਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 24, NULL);
