  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਕਲ ਨੂੰ ਆਵਾਜਾਈ ਦਾ ਕਿਹੋ ਜਿਹਾ ਸਾਧਨ ਦੱਸਿਆ ਗਿਆ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '1865347b-4222-4d6a-9714-d8182cdd9345', NULL, 1),
