  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭਾਰਤ ਵਿੱਚ ਸਾਈਕਲ ਨਿਰਮਾਣ ਦਾ ਪ੍ਰਮੁੱਖ ਕੇਂਦਰ ਕਿਹੜਾ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, 'abfe1099-664f-4c06-83ef-3beeefcb4f70', NULL, 1),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਕਲ ਦੀ ਸ਼ੁਰੂਆਤ ਕਿਹੜੀ ਸਦੀ ਵਿੱਚ ਹੋਈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '25ba3d72-d7f3-4a21-8629-210b1cd279d5', NULL, 1),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '9c6b8792-6136-48cf-a9d3-51caad2e18b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਹਿਲੀ ਸਾਈਕਲ ਕਦੋਂ ਅਤੇ ਕਿਸ ਨੇ ਤਿਆਰ ਕੀਤੀ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-823Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, 'e7f502f4-a4f4-4699-90f3-2020d1c9fb03', NULL, 1),
